/** The sound effect files, generated by `npm run sounds` (see `scripts/sounds.ts`). */
export type SoundEffect = 'place' | 'remove' | 'wall' | 'solved';

/** Metro bundles assets through `require`; each one resolves to an asset id. */
export const SOUND_SOURCES: Readonly<Record<SoundEffect, number>> = {
  place: require('../../assets/sounds/place.wav'),
  remove: require('../../assets/sounds/remove.wav'),
  wall: require('../../assets/sounds/wall.wav'),
  solved: require('../../assets/sounds/solved.wav'),
};
